-- 候选事项库第二批：继续从 350 条原始数据中筛选、去重和重写 50 条。
-- 候选库达到 150 条；家庭每天仍只会通过推荐 RPC 获得最多 10 条。

BEGIN;

WITH curated(
  source_id, num, perspective, tone, title, why, how, record, suggest,
  seasonal, sort_order, category, scene, min_age, max_age, seasons, tags
) AS (
  VALUES
  (7, '101', 'together', 'orange', '在真正的户外共同搭起一晚的帐篷', '从选位置、搭建到听着夜晚入睡，一家人会共同拥有一段与日常完全不同的记忆。', '选择正规营地和适宜天气，提前查看规则；让孩子参与铺垫、整理和收纳，火源及复杂工具由成人负责。', '拍下空地、搭好后的帐篷和第二天收起后的三张照片。', 'photo', true, 101, '户外探险', '户外', 5, 12, ARRAY['spring','summer','autumn']::text[], ARRAY['露营','合作','自然']::text[]),
  (15, '102', 'together', 'green', '全家分工，让一个凌乱角落重新舒服起来', '共同照顾生活空间，会让孩子感到家不是由某一个人默默维持的。', '只选一个抽屉或角落，每个人认领适龄任务；先决定保留什么，再清洁归位，不用把大扫除变成惩罚。', '拍下前后对比，并记下孩子主动想到的一种收纳办法。', 'photo', false, 102, '生活实践', '室内', 3, 12, ARRAY['all']::text[], ARRAY['家务','合作','责任']::text[]),
  (21, '103', 'together', 'pink', '玩一局输了也愿意再来的家庭桌游', '在安全的游戏里练习等待、守规则和面对输赢，是很真实的相处功课。', '共同选择适龄桌游，开局前说清规则；大人不故意放水，也不嘲笑失误，争议时一起查规则。', '记录本局最好笑的一次反转，以及输家仍愿意称赞对方的那句话。', 'text', false, 103, '益智游戏', '室内', 5, 12, ARRAY['all']::text[], ARRAY['桌游','规则','输赢']::text[]),
  (25, '104', 'parent', 'orange', '在纪念家人的日子讲一个真实的家族故事', '孩子知道自己从哪些人和故事中走来，会更具体地感受到家庭的延续。', '用照片、旧物或一次合适的祭扫讲述一位家人；尊重不同家庭习惯，不制造恐惧，也允许孩子提问死亡。', '写下这个故事里最想继续传下去的一种品质。', 'text', true, 104, '家庭回忆', '均可', 5, 12, ARRAY['spring']::text[], ARRAY['家族','纪念','传承']::text[]),
  (35, '105', 'together', 'green', '一起把一个坏掉的玩具修到能继续陪伴', '修理会让孩子看见物品可以被理解和照顾，而不是坏了就立刻丢弃。', '先一起判断故障和是否值得修；只处理安全、简单的结构，电池、尖锐零件和强力胶由成人操作。', '拍下拆开时的猜想、找到的问题和修好后的第一次试玩。', 'photo', false, 105, '生活实践', '室内', 5, 12, ARRAY['all']::text[], ARRAY['修理','珍惜','动手']::text[]),
  (44, '106', 'parent', 'pink', '把一本喜欢的书真正读给彼此听', '声音、停顿和依偎会让同一个故事变成只属于这个家的版本。', '由孩子挑书，轮流读或由家长读；遇到想说的地方可以停下来，不把共读变成识字测试。', '录下最喜欢的一小段朗读和孩子接上的一句评论。', 'voice', false, 106, '知识学习', '室内', 3, 12, ARRAY['all']::text[], ARRAY['共读','声音','陪伴']::text[]),
  (45, '107', 'together', 'green', '先猜答案，再完成一个安全的小实验', '亲手验证自己的猜想，会让孩子明白科学不是背答案，而是允许猜错再观察。', '从浮沉、影子或颜色混合等安全主题中选一个，先各自预测，再按步骤实验；不使用明火和不明化学品。', '做一张“我原来以为—实际发生—我又想问”的实验卡。', 'photo', false, 107, '知识学习', '室内', 4, 12, ARRAY['all']::text[], ARRAY['科学','实验','猜想']::text[]),
  (55, '108', 'together', 'orange', '一起写下一个最想留住的汉字', '慢慢写一个有意义的字，会把传统书写与当下真实的家庭愿望连在一起。', '各选一个代表最近心情或祝愿的字，用毛笔、硬笔或手指蘸水练习；不比较字是否标准。', '把两个人最满意的一张并排保存，并写下为什么选这个字。', 'photo', false, 108, '艺术欣赏', '室内', 5, 12, ARRAY['all']::text[], ARRAY['书法','汉字','表达']::text[]),
  (58, '109', 'together', 'pink', '做一块家人随时可以留下感谢的留言板', '被看见的小付出越具体，家里的爱越不需要只等特殊日子才表达。', '用纸板、白板或共享便签建立留言角，每个人先写或画一条真实感谢，不写要求和批评。', '一个月后拍下留言板，并选出一条最意外、最想长期保存的话。', 'photo', false, 109, '家庭仪式', '室内', 4, 12, ARRAY['all']::text[], ARRAY['感谢','表达','家庭']::text[]),
  (61, '110', 'parent', 'orange', '带孩子看看你认真工作的地方', '理解家长一天在做什么，会让“工作很忙”从模糊的缺席变成可以理解的生活。', '在单位允许和不影响他人的前提下短暂参观；介绍具体工作和一位合作伙伴，也诚实说说困难与成就感。', '请孩子画出他眼中的你的工作，并录下一个最想问的问题。', 'photo', false, 110, '生活实践', '室内', 5, 12, ARRAY['all']::text[], ARRAY['职业','理解父母','真实生活']::text[]),
  (62, '111', 'child', 'green', '为一位家人准备一份不看价格的心意', '观察家人真正喜欢什么，并亲手表达，会让孩子理解送礼的核心是理解而不是消费。', '先由孩子选对象和想传达的话，再决定制作、服务或小额购买；家长协助但不替他完成。', '送出前记录礼物和理由，送出后记下对方最真实的反应。', 'photo', false, 111, '家庭仪式', '均可', 3, 12, ARRAY['all']::text[], ARRAY['礼物','观察','表达爱']::text[]),
  (63, '112', 'together', 'pink', '从打鸡蛋开始，做一只属于今年的生日蛋糕', '每年共同完成的味道和不完美装饰，会比买来的标准样式更像一段家庭时间。', '让过生日的人决定口味和主题，按年龄参与称量、搅拌或装饰；烤箱、刀具和过敏风险由成人负责。', '拍下今年的设计草图、成品和吹蜡烛前的愿望表情。', 'photo', true, 112, '节日仪式', '室内', 4, 12, ARRAY['all']::text[], ARRAY['生日','烘焙','仪式']::text[]),
  (64, '113', 'together', 'green', '一起洗好、晾好并叠好一小篮衣服', '完成一件从开始到收尾的家务，会让孩子真实感到自己也是这个家的贡献者。', '只处理少量普通衣物，让孩子按颜色分类、夹袜子或叠自己的衣服；洗涤剂和机器由成人管理。', '拍下各自最有创意的一种叠法，并说一句谢谢搭档。', 'photo', false, 113, '生活实践', '室内', 3, 10, ARRAY['all']::text[], ARRAY['家务','自理','合作']::text[]),
  (69, '114', 'together', 'orange', '跨年时互相说一件感谢和一件期待', '在时间交替的节点回望彼此，会让新年不只是熬夜和倒计时。', '不必等到零点，找一个全家清醒的时刻，轮流说今年感谢家人的一件事和明年想一起完成的一件事。', '录下倒数和每个人的两个答案，明年再重新播放。', 'voice', true, 114, '节日仪式', '室内', 4, 12, ARRAY['winter']::text[], ARRAY['跨年','感谢','期待']::text[]),
  (76, '115', 'together', 'green', '看一集纪录片，把惊讶变成一个新问题', '真实世界带来的惊讶如果被继续追问，会成为孩子主动探索的起点。', '共同选择适龄自然、科学或人文纪录片，只看能保持注意的一段；结束后各提出一个仍不知道答案的问题。', '写下两个问题，并任选一个继续查到明白为止。', 'text', false, 115, '知识学习', '室内', 5, 12, ARRAY['all']::text[], ARRAY['纪录片','提问','探索']::text[]),
  (80, '116', 'child', 'pink', '让孩子重新安排自己的衣柜一层', '能决定物品放在哪里，会让整理从服从要求变成真正可持续的自我管理。', '只选孩子够得到的一层，让他按自己的使用习惯分类；家长只提醒安全和空间限制，保留他的逻辑。', '一周后拍下仍然好用的布局，并请孩子介绍为什么这样放。', 'video', false, 116, '生活实践', '室内', 4, 12, ARRAY['all']::text[], ARRAY['整理','自主','生活能力']::text[]),
  (82, '117', 'child', 'orange', '共同改造一个真正属于孩子的小角落', '参与决定光线、颜色和摆放，会让孩子感到自己的需要和审美在家里有位置。', '不必重新装修，只选一处书桌、床边或展示角；先问孩子想在这里做什么，再用现有物品调整。', '拍下改造前后，并让孩子为这个角落起一个名字。', 'photo', false, 117, '创意手工', '室内', 3, 12, ARRAY['all']::text[], ARRAY['空间','自主','归属感']::text[]),
  (83, '118', 'parent', 'pink', '用正确名字认识身体，也练习说“不”', '清楚身体边界、隐私部位和可信任求助对象，是孩子保护自己的基础能力。', '使用适龄绘本或人体图，平静说出身体部位的正确名称；说明隐私、同意、可以拒绝，以及不舒服时找谁。', '和孩子共同列出三位可以求助的可信任大人，不记录私密对话内容。', 'text', false, 118, '安全教育', '室内', 3, 12, ARRAY['all']::text[], ARRAY['身体边界','同意','自我保护']::text[]),
  (87, '119', 'child', 'green', '一起装扮成孩子喜欢的角色，并演一小段故事', '认真进入孩子热爱的角色，会让他感到自己的兴趣被尊重，也能借故事表达自己。', '优先利用现有衣物和纸板制作，不追求昂贵还原；由孩子分配角色和剧情，任何人都可以拒绝不舒服的装扮。', '录下角色登场和孩子即兴说出的第一句台词。', 'video', false, 119, '创意手工', '室内', 3, 12, ARRAY['all']::text[], ARRAY['角色扮演','想象','共同创作']::text[]),
  (100, '120', 'parent', 'orange', '做一次月饼，也讲讲你记得的中秋', '家庭关于月亮、团圆和味道的记忆，会在一次共同制作中传给下一代。', '选择安全的简化做法或制作冰皮月饼，让孩子参与压模和包装；边做边讲你小时候怎样过中秋。', '拍下每个人设计的花纹，并录下孩子给月亮说的一句话。', 'photo', true, 120, '节日仪式', '室内', 4, 12, ARRAY['autumn']::text[], ARRAY['中秋','传统','家族记忆']::text[]),
  (102, '121', 'together', 'green', '把一团面变成一碗自己做的面条', '从没有形状的面团到真正入口的主食，会给孩子很完整的劳动成果感。', '选简单的手擀面或揪面片，让孩子揉、按或揪出自己的形状；刀具、沸水和生熟卫生由成人负责。', '拍下最长、最短和最奇怪的三根面，以及端上桌的成品。', 'photo', false, 121, '厨房美食', '室内', 4, 12, ARRAY['all']::text[], ARRAY['面食','劳动','合作']::text[]),
  (111, '122', 'child', 'pink', '和朋友完成一次双方都愿意的以物易物', '交换能让孩子理解价值来自双方需要，而不是只有价格一个答案。', '只选双方拥有处置权的小物，先说明物品情况和是否后悔；不利用年龄差强迫交换，家长只帮助确认公平。', '记录交换前双方为什么想要对方的物品，以及一周后是否仍满意。', 'text', false, 122, '财商启蒙', '均可', 6, 12, ARRAY['all']::text[], ARRAY['交换','价值','协商']::text[]),
  (112, '123', 'child', 'orange', '让孩子参与策划一次温暖而不过度的生日聚会', '生日被认真商量和共同准备，会让仪式感来自关系，而不是规模和消费。', '让孩子决定最想邀请的人和一个核心活动，一起制定预算、准备邀请和感谢；尊重不爱热闹的选择。', '聚会后写下今天谁做的一件小事让自己最开心。', 'text', true, 123, '节日仪式', '均可', 4, 12, ARRAY['all']::text[], ARRAY['生日','策划','友谊']::text[]),
  (116, '124', 'together', 'green', '在冬天的玻璃雾气上留下一幅会消失的画', '知道作品很快会消失，反而会让你们更专注于一起创造的当下。', '选择安全、不会影响视线的室内玻璃，用呵气产生小块雾面后轮流添画；不用在行驶车辆玻璃上操作。', '在图案消失前拍一张，并记下是谁补上了最后一笔。', 'photo', true, 124, '创意手工', '室内', 3, 10, ARRAY['winter']::text[], ARRAY['冬天','短暂艺术','合作']::text[]),
  (118, '125', 'together', 'orange', '合作做一个真的能够转起来的摩天轮模型', '从图纸到转动的一刻，会把空间想象、失败调整和共同欢呼连接起来。', '使用适龄积木、纸板套件或安全零件，先分工搭底座和轮盘；卡住时先一起找原因，不替孩子直接修完。', '录下第一次完整转一圈，以及此前一次失败的样子。', 'video', false, 125, '创意手工', '室内', 6, 12, ARRAY['all']::text[], ARRAY['模型','机械','解决问题']::text[]),
  (120, '126', 'child', 'pink', '亲手做一张只写给某个人的节日卡片', '把对一个人的观察写进卡片，比复制一句祝福更能练习真诚表达。', '由孩子选择收卡人、材料和想说的话；家长可以代写口述，但保留孩子原本的措辞和画法。', '送出前拍下卡片内外，并记下其中最具体的一句祝福。', 'photo', true, 126, '创意手工', '室内', 3, 12, ARRAY['all']::text[], ARRAY['贺卡','节日','表达']::text[]),
  (124, '127', 'together', 'green', '用阳光和水雾在家门口找出一道小彩虹', '亲手制造一个转瞬即逝的自然现象，会让光学知识和惊喜同时发生。', '在有阳光的户外用喷壶形成细雾，背对太阳调整角度；避开湿滑地面、行人和电子设备。', '拍下终于出现的彩虹，并录下你们之前猜了多少个角度。', 'photo', true, 127, '知识学习', '户外', 4, 10, ARRAY['spring','summer','autumn']::text[], ARRAY['光学','彩虹','实验']::text[]),
  (126, '128', 'child', 'orange', '请孩子用积木搭一座“住进去会开心”的城堡', '开放的搭建没有标准答案，孩子会通过空间和细节表达自己重视什么。', '给出足够但有限的积木，不提供成品图；家长只按孩子指令协助，并认真询问每个空间的用途。', '录一段城堡导览，特别保存孩子最看重的那个房间。', 'video', false, 128, '创意手工', '室内', 3, 10, ARRAY['all']::text[], ARRAY['积木','空间想象','表达']::text[]),
  (129, '129', 'together', 'green', '合作完成一幅需要耐心的大拼图', '在很长一段时间里共同寻找小线索，会留下关于分工、坚持和互相等待的记忆。', '按年龄选择难度，先商量分边框、颜色或区域；可以分几天完成，不因进度责怪或抢走对方部分。', '每天收工前拍一张进度，完成后找出最难找到的那一片。', 'photo', false, 129, '益智游戏', '室内', 5, 12, ARRAY['all']::text[], ARRAY['拼图','耐心','合作']::text[]),
  (130, '130', 'together', 'pink', '在草地上完成十次真正传到脚下的足球配合', '比进几个球更重要的是看见队友、调整力量并为一次配合共同开心。', '在安全空地从近距离传球开始，不设输赢；由孩子选择挑战次数，成人控制力量并留意周围行人。', '录下连续完成目标的那一组传球和庆祝动作。', 'video', false, 130, '运动健身', '户外', 4, 12, ARRAY['spring','summer','autumn']::text[], ARRAY['足球','配合','运动']::text[]),
  (135, '131', 'child', 'orange', '把一个熟悉故事排成五分钟家庭小剧场', '从分配角色到共同谢幕，孩子会体验把想象组织成一场大家都参与的作品。', '由孩子选故事、导演和分配角色，用家中物品做简单道具；允许忘词和临时改剧情，不强迫表演。', '保存手写节目单，并录下最出乎意料的一次即兴发挥。', 'video', false, 131, '艺术欣赏', '室内', 5, 12, ARRAY['all']::text[], ARRAY['戏剧','合作','表达']::text[]),
  (138, '132', 'parent', 'green', '把你小时候会唱的一首歌教给孩子', '一首从童年传来的歌，会让孩子听见家长也曾被别人哄过、陪伴过。', '选一首适龄且你真正记得的歌，先讲在哪里学会，再一句句唱；跑调和忘词都可以一起补。', '录下你们第一次完整合唱，并保留中途笑场的部分。', 'voice', false, 132, '艺术欣赏', '室内', 3, 12, ARRAY['all']::text[], ARRAY['童年歌曲','传承','合唱']::text[]),
  (143, '133', 'child', 'pink', '在家布置一场由孩子破解的寻宝游戏', '被认真准备的一连串线索，会让孩子感到惊喜，也练习观察和推理。', '按年龄设计三到五条安全线索，不藏在高处、药品或危险区域；终点可以是一封信或共同活动，不必是礼物。', '记录最难的一条线索、孩子怎样想通，以及找到终点的表情。', 'video', false, 133, '益智游戏', '室内', 4, 12, ARRAY['all']::text[], ARRAY['寻宝','推理','惊喜']::text[]),
  (147, '134', 'together', 'orange', '画一张脸谱，认识一种京剧颜色的性格', '传统艺术从亲手选择颜色开始，会比只记名称更容易留下兴趣和感受。', '先看少量适龄资料，选择一种颜色和人物性格，再在纸面具上创作；不用颜料直接涂脸，避免过敏。', '戴着或举着作品合影，并让孩子用一句话介绍这个角色。', 'photo', false, 134, '艺术欣赏', '室内', 5, 12, ARRAY['all']::text[], ARRAY['京剧','脸谱','传统文化']::text[]),
  (160, '135', 'parent', 'green', '带孩子走一遍你曾经上学的路', '真实的校门、操场和路口，会让家长的童年从故事变成孩子能够站进去的地方。', '在学校允许参观的范围内进行，不打扰教学；讲一件开心、一件困难和一个当年的朋友。', '在最有记忆的地点拍一张现在的合影，并找找它和过去有什么不同。', 'photo', false, 135, '家庭回忆', '户外', 5, 12, ARRAY['all']::text[], ARRAY['学校','父母童年','代际理解']::text[]),
  (167, '136', 'child', 'pink', '一起画出孩子梦想中的家，并认真听他介绍', '一个家里应该有什么，常常藏着孩子对安全、自由和陪伴最真实的理解。', '让孩子自由画，不纠正现实性；家长也画一张，然后互相参观，只问“这里为什么重要”。', '录下孩子介绍最特别房间的一段话，并保存两张设计图。', 'voice', false, 136, '创意手工', '室内', 4, 12, ARRAY['all']::text[], ARRAY['梦想之家','安全感','表达']::text[]),
  (168, '137', 'together', 'orange', '互换角色一小时，按对方的视角过生活', '暂时站到对方的位置，会让日常抱怨变成理解，也带来很多只有家人才懂的笑点。', '共同约定安全范围，孩子模拟家长安排一项家务，家长按孩子方式完成一段日常；不借模仿讽刺对方。', '结束后各说一件“原来你并不容易”的发现并录下来。', 'voice', false, 137, '亲子陪伴', '室内', 5, 12, ARRAY['all']::text[], ARRAY['角色互换','共情','家庭生活']::text[]),
  (179, '138', 'child', 'green', '用放大镜跟随一只昆虫，但不带走它', '靠近观察又克制捕捉，会让好奇心和尊重生命同时发生。', '在安全公园寻找常见昆虫，保持距离、不触碰蜂类和不明虫；让孩子观察颜色、脚和移动方式后原地离开。', '画下它的一条路线，并回家查出可能的名字。', 'photo', true, 138, '自然探索', '户外', 4, 12, ARRAY['spring','summer','autumn']::text[], ARRAY['昆虫','观察','生命尊重']::text[]),
  (182, '139', 'together', 'pink', '在海边合作造一座终会被海浪带走的沙堡', '明知道作品不会永久存在，仍一起认真建造，会让孩子体验创造和告别。', '选择允许活动且远离涨潮危险的沙滩，使用手和简单沙具；不挖深坑，离开前填平并带走物品。', '拍下刚完成和海浪改变后的两张照片。', 'photo', true, 139, '创意手工', '户外', 3, 12, ARRAY['summer','autumn']::text[], ARRAY['沙堡','海边','创造']::text[]),
  (187, '140', 'together', 'orange', '在第一场合适的雪里堆一个有名字的雪人', '季节限定的共同作品，会让某一个冬天拥有清楚的样子和名字。', '在安全空地做好保暖，避开道路和屋檐落冰；由孩子决定造型，感到冷或湿就及时结束。', '和雪人合影，记下它的名字、性格和后来什么时候消失。', 'photo', true, 140, '自然探索', '户外', 3, 12, ARRAY['winter']::text[], ARRAY['雪人','冬天','季节记忆']::text[]),
  (188, '141', 'together', 'green', '在果园亲手摘下正当季的一颗果实', '从枝头到手心再到入口，孩子会更真实地理解成熟、劳动和食物来之不易。', '选择正规采摘园，听从工作人员说明；只摘允许的成熟果实，不攀爬和浪费，采后一起清洗品尝。', '拍下找到、摘下和第一次品尝的三个瞬间。', 'photo', true, 141, '自然探索', '户外', 3, 12, ARRAY['summer','autumn']::text[], ARRAY['采摘','食物来源','劳动']::text[]),
  (194, '142', 'child', 'pink', '让孩子当口令员，玩一轮“一二三木头人”', '轮流发出口令和控制身体，会让规则、观察和欢笑同时发生。', '选择平整安全的空地，先约定不能推撞；轮流做口令员，允许孩子发明一个新的静止姿势。', '录下全家最难保持不笑的一轮。', 'video', false, 142, '运动健身', '户外', 3, 10, ARRAY['spring','summer','autumn']::text[], ARRAY['传统游戏','反应','轮流']::text[]),
  (209, '143', 'child', 'orange', '请孩子参与规划一次真实会出发的短途旅行', '当路线、时间和预算真的会影响旅程，规划能力就不再只是纸面练习。', '给出目的地和明确边界，让孩子从交通、一个景点或一顿饭中负责一项选择；共同查看开放时间和天气。', '保存孩子负责的那页计划，并在回来后标注实际与计划的不同。', 'photo', false, 143, '旅行探险', '室内', 7, 12, ARRAY['all']::text[], ARRAY['旅行规划','选择','真实任务']::text[]),
  (220, '144', 'together', 'green', '一起用一种陌生乐器奏出第一个完整节奏', '当两个人都从不会开始，练习和倾听会比演奏得像不像更重要。', '选择容易体验的口琴、尤克里里、手鼓或键盘，从一个短节奏开始；控制音量和时长，不要求长期报班。', '录下第一次混乱和第一次合上的两个版本。', 'voice', false, 144, '艺术欣赏', '室内', 5, 12, ARRAY['all']::text[], ARRAY['乐器','节奏','共同学习']::text[]),
  (222, '145', 'parent', 'pink', '教会彼此一种棋，并完整下完第一局', '棋盘上的等待、预判和接受失误，会让大人与孩子在平等规则里认真相遇。', '选择围棋、象棋或简单棋类，只教足够开局的规则；允许查提示，不用第一局就讲完所有技巧。', '保存终局棋盘，并请双方各指出自己最满意的一步。', 'photo', false, 145, '益智游戏', '室内', 6, 12, ARRAY['all']::text[], ARRAY['棋类','策略','耐心']::text[]),
  (228, '146', 'together', 'orange', '参加一次真正需要你们动手的社区活动', '当孩子在熟悉的社区里贡献一点力量，会更容易理解公共空间也需要共同照顾。', '选择正规、适龄的社区活动，如种植、清洁或节庆布置；事前说明任务，孩子不愿参与的环节可以退出。', '记录你们共同完成的一处变化，以及遇见的一位新邻居。', 'text', false, 146, '社交能力', '均可', 5, 12, ARRAY['all']::text[], ARRAY['社区','公共责任','参与']::text[]),
  (235, '147', 'child', 'green', '不用手机，让孩子带你判断一次东西南北', '把太阳、影子和地标用于真实辨向，会让方向感成为可以依靠的生活能力。', '在熟悉安全的户外先找太阳或已知地标，再用指南针验证；让孩子说出判断过程，不把走错当失败。', '画一张以当前位置为中心的四方向小地图。', 'photo', false, 147, '生活实践', '户外', 6, 12, ARRAY['all']::text[], ARRAY['方向感','地图','生活能力']::text[]),
  (246, '148', 'together', 'pink', '躺在草地上，把三朵云看成不同的故事', '什么都不急着完成的共同想象，会给亲子留下一段真正松弛的时间。', '选择允许停留、干燥安全的草地，放下手机看十分钟；轮流指出一朵云像什么，并接着编下去。', '不必拍清云，只录下你们共同编出的那段短故事。', 'voice', true, 148, '自然探索', '户外', 3, 12, ARRAY['spring','summer','autumn']::text[], ARRAY['看云','想象','慢陪伴']::text[]),
  (259, '149', 'child', 'orange', '在植物园寻找三种“像从别的星球来的”植物', '带着一个有趣任务观察，会让孩子主动发现叶片、颜色和生存方式的差异。', '在正规步道由孩子挑选三种最奇特的植物，阅读标牌或回家查资料；不触摸未知植物、不离开步道。', '为三种植物分别起一个外星名字，再记录它们的真实名称。', 'photo', true, 149, '自然探索', '户外', 4, 12, ARRAY['spring','summer','autumn']::text[], ARRAY['植物园','观察','命名']::text[]),
  (261, '150', 'child', 'green', '带一只指南针，在公园完成三次找方向任务', '把抽象的东南西北用于移动和寻找，会让孩子获得真实的小小独立感。', '在开阔安全公园先示范指南针，再让孩子找到北方、朝一个方向走若干步并返回；成人始终掌握路线。', '记录三次任务结果，以及一次读错后怎样重新校准。', 'text', false, 150, '户外探险', '户外', 7, 12, ARRAY['spring','summer','autumn']::text[], ARRAY['指南针','方向','户外技能']::text[])
)
INSERT INTO public.levels (
  num, perspective, tone, title, why, how, record, suggest,
  sealed, seal_until, sealed_on, seasonal, kid, sort_order,
  category, scene, min_age, max_age, seasons, tags, quality_score, active, source_ref
)
SELECT
  num, perspective, tone, title, why, how, record, suggest,
  false, NULL, NULL, seasonal, NULL, sort_order,
  category, scene, min_age, max_age, seasons, tags, 85, true, 'source-json:' || source_id
FROM curated
ON CONFLICT (num) DO UPDATE SET
  perspective = EXCLUDED.perspective,
  tone = EXCLUDED.tone,
  title = EXCLUDED.title,
  why = EXCLUDED.why,
  how = EXCLUDED.how,
  record = EXCLUDED.record,
  suggest = EXCLUDED.suggest,
  seasonal = EXCLUDED.seasonal,
  sort_order = EXCLUDED.sort_order,
  category = EXCLUDED.category,
  scene = EXCLUDED.scene,
  min_age = EXCLUDED.min_age,
  max_age = EXCLUDED.max_age,
  seasons = EXCLUDED.seasons,
  tags = EXCLUDED.tags,
  quality_score = EXCLUDED.quality_score,
  active = EXCLUDED.active,
  source_ref = EXCLUDED.source_ref;

COMMIT;
